namespace Chondrite.Store;

/// <summary>
/// A randomly generated 128-bit value used to distinguish otherwise identical
/// persisted records. A nonce has no ordering, provenance, or logical-entity semantics.
/// </summary>
/// <remarks>
/// Its canonical representation is the 16-byte RFC 4122/network-order GUID.
/// Nonces must be generated explicitly and are never generated by serialization.
/// This is not an encryption nonce; encryption algorithms have their own requirements.
/// The default value (an empty GUID) is invalid for persistence.
/// </remarks>
public readonly record struct Nonce
{
    /// <summary>The GUID carried by this nonce.</summary>
    public Guid idValue { get; }

    /// <summary>Creates a nonce from a nonempty GUID.</summary>
    public Nonce(Guid idValue)
    {
        if (idValue == Guid.Empty)
            throw new ArgumentException("A nonce cannot contain an empty GUID.", nameof(idValue));
        this.idValue = idValue;
    }

    /// <summary>Generates a fresh random nonce.</summary>
    public static Nonce oNew() => new(Guid.NewGuid());

    /// <summary>Formats the underlying GUID for diagnostics.</summary>
    public override string ToString() => idValue.ToString("D");
}
